function compile(node, out = []) {
  if (node.kind === 'num') { out.push(['PUSH', node.value]); return out; }
  if (node.kind === 'bin') {
    compile(node.left, out);
    compile(node.right, out);
    out.push([{ '+': 'ADD', '-': 'SUB', '*': 'MUL', '/': 'DIV' }[node.op]]);
    return out;
  }
  throw new Error('모르는 노드');
}

function run(code) {
  const st = [];
  for (const [op, arg] of code) {
    if (op === 'PUSH') { st.push(arg); continue; }
    const b = st.pop(), a = st.pop();
    st.push(op === 'ADD' ? a + b : op === 'SUB' ? a - b : op === 'MUL' ? a * b : a / b);
  }
  return st.pop();
}
